import { MONSTER_DATA } from "@hunt/hunt-data/monarch";
import { QuizTaskComponent, type QuizQuestion } from "@hunt/puzzle-components";
import { createRoot } from "react-dom/client";

function shuffle<T>(array: T[]): T[] {
  const shuffled = [...array];
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }
  return shuffled;
}

const allQuestions: QuizQuestion[] = Object.values(MONSTER_DATA)
  .flatMap((zone) => Object.values(zone))
  .filter((monster): monster is typeof monster & { silhouetteSrc: string } =>
    Boolean(monster.silhouetteSrc),
  )
  .map((monster, index) => ({
    id: index,
    image: monster.silhouetteSrc,
    answer: monster.name,
  }));

const possibleAnswers = [
  ...new Set(
    allQuestions.map((q) => q.answer).filter((a): a is string => Boolean(a)),
  ),
].sort();

const NUMBER_OF_QUESTIONS = 10;

/** Get a fresh random set each time (used on initial load and on "Play again") */
const getQuestions = (): QuizQuestion[] =>
  shuffle(allQuestions).slice(0, NUMBER_OF_QUESTIONS);

const rootEl = document.getElementById("whos-that-puzzmon-root");
if (rootEl) {
  const root = createRoot(rootEl);
  root.render(
    <QuizTaskComponent
      taskSlug="whos_that_puzzmon"
      localQuestions={getQuestions}
      quizInstructions="Name the Puzzmon shown"
      refreshTimeInSeconds={10}
      numberOfQuestions={NUMBER_OF_QUESTIONS}
      possibleAnswers={possibleAnswers}
    />,
  );
} else {
  console.error(
    "Could not mount Who's That Puzzmon: #whos-that-puzzmon-root not found",
  );
}
